package com.icbc.changzhou.ipam;

import java.nio.file.*;
import java.sql.*;
import java.time.Instant;
import org.mindrot.jbcrypt.BCrypt;

/** Offline/operational SQLite utility: online backup, integrity check, and stopped-service restore. */
public final class DatabaseTool {
  public static void main(String[] args) throws Exception {
    if (args.length < 2 || args.length > 4) throw new IllegalArgumentException("用法: DatabaseTool check <db> | backup <db> <backup.db> | restore <db> <backup.db> | reset-admin <db> <password-file> [username]");
    Path db=Paths.get(args[1]).toAbsolutePath().normalize();
    if("check".equals(args[0])) { check(db); return; }
    if("reset-admin".equals(args[0])) { if(args.length<3||args.length>4) throw new IllegalArgumentException("reset-admin 需要数据库和密码文件。"); resetAdmin(db,Paths.get(args[2]).toAbsolutePath().normalize(),args.length==4?args[3]:"admin"); return; }
    if(args.length!=3) throw new IllegalArgumentException("backup/restore 需要数据库和备份文件路径。");
    Path backup=Paths.get(args[2]).toAbsolutePath().normalize();
    if("backup".equals(args[0])) backup(db,backup); else if("restore".equals(args[0])) restore(db,backup); else throw new IllegalArgumentException("未知命令。");
  }
  static void check(Path db)throws Exception {try(Connection c=DriverManager.getConnection("jdbc:sqlite:"+db);Statement s=c.createStatement();ResultSet r=s.executeQuery("PRAGMA integrity_check")){if(!r.next()||!"ok".equalsIgnoreCase(r.getString(1)))throw new IllegalStateException("SQLite integrity_check 失败。");System.out.println("PASS|SQLITE_INTEGRITY|ok");}}
  static void backup(Path db,Path target)throws Exception {if(!Files.isRegularFile(db))throw new IllegalArgumentException("数据库不存在: "+db);Files.createDirectories(target.getParent());if(Files.exists(target))throw new IllegalArgumentException("备份目标已存在，拒绝覆盖: "+target);try(Connection c=DriverManager.getConnection("jdbc:sqlite:"+db);Statement s=c.createStatement()){String safe=target.toString().replace("'","''");s.execute("VACUUM INTO '"+safe+"'");}check(target);System.out.println("PASS|SQLITE_BACKUP|"+target);}
  static void restore(Path db,Path source)throws Exception {if(!Files.isRegularFile(source))throw new IllegalArgumentException("备份文件不存在: "+source);check(source);Files.createDirectories(db.getParent());Path rollback=db.resolveSibling(db.getFileName()+".before-restore");if(Files.exists(db)){if(Files.exists(rollback))throw new IllegalStateException("回滚副本已存在，请先处理: "+rollback);Files.move(db,rollback);}Files.copy(source,db,StandardCopyOption.REPLACE_EXISTING);Files.deleteIfExists(db.resolveSibling(db.getFileName()+"-wal"));Files.deleteIfExists(db.resolveSibling(db.getFileName()+"-shm"));check(db);System.out.println("PASS|SQLITE_RESTORE|"+db+"|ROLLBACK_COPY|"+rollback);}
  static void resetAdmin(Path db,Path passwordFile,String username)throws Exception {if(!Files.isRegularFile(db))throw new IllegalArgumentException("数据库不存在: "+db);String password;try{password=Files.readString(passwordFile).trim();}finally{Files.deleteIfExists(passwordFile);}if(password.length()<12||password.length()>72||!password.matches(".*[A-Za-z].*")||!password.matches(".*[0-9].*"))throw new IllegalArgumentException("密码须为 12–72 位，且同时包含字母和数字。");try(Connection c=DriverManager.getConnection("jdbc:sqlite:"+db)){c.setAutoCommit(false);try{long adminId=-1;try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id FROM sys_user WHERE role='ADMIN' ORDER BY id LIMIT 1")){if(r.next())adminId=r.getLong(1);}String now=Instant.now().toString();if(adminId<0){if(username.length()<3||username.length()>64)throw new IllegalArgumentException("管理员账号长度必须为 3–64。");try(PreparedStatement p=c.prepareStatement("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password,password_changed_at) VALUES(?,?,?, 'ADMIN',1,1,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,username);p.setString(2,BCrypt.hashpw(password,BCrypt.gensalt(12)));p.setString(3,"恢复管理员");p.setString(4,now);p.executeUpdate();ResultSet k=p.getGeneratedKeys();k.next();adminId=k.getLong(1);}}else{try(PreparedStatement p=c.prepareStatement("UPDATE sys_user SET password_hash=?,is_active=1,must_change_password=1,failed_login_count=0,locked_until=NULL,password_changed_at=?,updated_at=? WHERE id=?")){p.setString(1,BCrypt.hashpw(password,BCrypt.gensalt(12)));p.setString(2,now);p.setString(3,now);p.setLong(4,adminId);p.executeUpdate();}}try(PreparedStatement p=c.prepareStatement("UPDATE sys_session SET revoked_at=? WHERE user_id=? AND revoked_at IS NULL")){p.setString(1,now);p.setLong(2,adminId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO audit_log(action,target_type,target_id,result,detail_json) VALUES('RECOVER_ADMIN','USER',?,'SUCCESS','{\"source\":\"local-recovery-tool\"}')")){p.setString(1,String.valueOf(adminId));p.executeUpdate();}c.commit();System.out.println("PASS|ADMIN_PASSWORD_RESET|userId="+adminId+"|mustChangePassword=true");}catch(Exception e){c.rollback();throw e;}}}
}
